(188833, 10874, 3127, '<td valign="top">Great color and perspective. Really interesting shot.</td>', 'Great color and perspective. Really interesting shot.', '2003-01-13 11:27:22.000000', NULL, 1),
(188834, 10701, 3294, '<td valign="top">Beautiful colors.. but why is so much of the land blurry?  Could have cropped this tighter, since a third of this is completely black.</td>', 'Beautiful colors.. but why is so much of the land blurry?  Could have cropped this tighter, since a third of this is completely black.', '2003-01-13 11:27:25.000000', NULL, 1),
(188837, 10972, 3294, '<td valign="top">The black and white causes this photo to be very busy.  Might have been more effective in color?  Dunno.</td>', 'The black and white causes this photo to be very busy.  Might have been more effective in color?  Dunno.', '2003-01-13 11:28:31.000000', NULL, 1),
(188838, 10951, 3294, '<td valign="top">Powerlines?  hehe  I would have liked to see the whole tree, the right side seems cropped off.</td>', 'Powerlines?  hehe  I would have liked to see the whole tree, the right side seems cropped off.', '2003-01-13 11:29:40.000000', NULL, 1),
(188840, 10942, 3127, '<td valign="top">Great and somewhat spooky photo.</td>', 'Great and somewhat spooky photo.', '2003-01-13 11:31:29.000000', NULL, 1),
(188841, 10869, 3294, '<td valign="top">Seems a little soft.  But I like the trail and river side by side.</td>', 'Seems a little soft.  But I like the trail and river side by side.', '2003-01-13 11:31:51.000000', NULL, 1),
(188842, 10976, 3127, '<td valign="top">Really beautiful scenery. Great shot.</td>', 'Really beautiful scenery. Great shot.', '2003-01-13 11:32:26.000000', NULL, 1),
