(191568, 10699, 5121, '<td valign="top">Not enough of the tree seen here. If you want to shoot a huge expanse of sky like this, get right under the tree and shoot upwards, but make sure (unless it''s a totally awesome sky) you got enough of your main subject to fill the frame.</td>', 'Not enough of the tree seen here. If you want to shoot a huge expanse of sky like this, get right under the tree and shoot upwards, but make sure (unless it''s a totally awesome sky) you got enough of your main subject to fill the frame.', '2003-01-15 05:59:28.000000', NULL, 1),
(191569, 10809, 5340, '<td valign="top">Great shot!</td>', 'Great shot!', '2003-01-15 06:01:11.000000', NULL, 1),
