(192786, 11018, 6263, '<td valign="top">The horizon is too 50/50 for me but a good capture.</td>', 'The horizon is too 50/50 for me but a good capture.', '2003-01-16 16:18:01.000000', NULL, 1),
(192787, 10814, 6263, '<td valign="top">Good composition, good shadows.  I like the coloring.</td>', 'Good composition, good shadows.  I like the coloring.', '2003-01-16 16:19:09.000000', NULL, 1),
