(193688, 11020, 6007, '<td valign="top">Good job =)</td>', 'Good job =)', '2003-01-17 19:27:07.000000', NULL, 1),
(193689, 10892, 6007, '<td valign="top">A+</td>', 'A+', '2003-01-17 19:27:20.000000', NULL, 1),
